import glob,json,collections
for f in sorted(glob.glob('runs/45e83829807b4e04b831c48a8359d7f1/NA*.json')):
 d=json.load(open(f)); c=d['candidate']; t,k=c['parent'],c['child']; a,b=map(int,(c['left_1based'],c['right_1based']))
 print('\\n',c['key'],d['child_ps_orientation_anchors'],d['excluded_vcf_records'])
 for sp,v in d['endpoint_read_patterns_by_ps_hp'].items(): print(sp,v)
 for p,s in d['snvs'].items():
  h=s['transmitted_target_hp']; tc=s['calls'][t]; cc=s['calls'][k]; oc=s['calls'][d['other_parent']]
  if h or int(p) in (a,b) or (a-1500<=int(p)<=b+1500 and tc['gt'] and None not in tc['gt'] and len(set(tc['gt']))==2):
   print(p,''.join(s['alleles']),h,'GT/GQ',[(x['gt'],x['ps'],x['gq']) for x in (tc,oc,cc)],s['read_bases_by_ps_hp'][t],s['read_bases_by_ps_hp'][k])
PY"

